import * as Comlink from 'comlink';

let intervalId: number | null = null;

const api = {
  start(callback) {
    if (intervalId) return;
    // The worker runs independent of the main thread's event loop
    intervalId = self.setInterval(() => {
      callback(0); // Pulse sent to main thread
    }, 1000);
  },
  pause() {
    if (intervalId) {
      self.clearInterval(intervalId);
      intervalId = null;
    }
  }
};

Comlink.expose(api);

export const useTimeStore = create<TimeState>()(
  persist(
    (set, get) => ({
      timeLeft: DEFAULT_DURATION,
      isRunning: false,
      startTimer: async () => {
        set({ isRunning: true });
        // Start the worker proxy
        await getWorker().start(Comlink.proxy(() => get().tick()));
      },
      tick: () => {
        const { timeLeft, mode } = get();
        if (timeLeft > 0) {
          set({ timeLeft: timeLeft - 1 });
        } else {
          events.emit('timer:complete', mode);
        }
      }
    }),
    { name: 'pomo-time-storage' }
  )
);
